 public static void Run(){SkillCatalog.VerificationAllV=false;int checks=0;void Check(bool b,string name){if(!b)throw new Exception("SKILLS FAIL: "+name);checks++;Console.WriteLine("SKILLS PASS: "+name);}
 Check(SkillCatalog.All.Length==512,"512 published skill records from CCP build 3569502");Check(SkillCatalog.Database.Types.Count==6962,"all 6962 published requirement records imported");
 foreach(var s in SkillCatalog.All){Check(s.Rank>0&&SkillCatalog.AttributeNames.ContainsKey(s.Primary)&&SkillCatalog.AttributeNames.ContainsKey(s.Secondary),s.SourceName+" training data");Check(s.Requirements.All(r=>SkillCatalog.ById.ContainsKey(r.Skill)&&r.Level is >=1 and <=5),s.SourceName+" prerequisite references");var profile=new PilotSkills();var chain=profile.Expand([new(s.Id,5)],false);Check(profile.Validate(chain).Length==0,s.SourceName+" acyclic full prerequisite expansion");}
 var g=SkillCatalog.ById[3300];Check(g.Threshold(1)==250&&g.Threshold(2)==1415&&g.Threshold(3)==8000&&g.Threshold(4)==45255&&g.Threshold(5)==256000,"exact rank-one SP thresholds");
 DateTime t=DateTime.UtcNow.AddDays(-10);var p=new PilotSkills{ProcessedUtc=t,Injected=[3300],Queue=[new(3300,1),new(3300,2)]};double rate=p.Rate(3300,t);p.Advance(t.AddMinutes(250/rate));Check(p.Trained(3300)==1&&p.Queue.Count==1,"level completion advances queue");p.Advance(t.AddMinutes(1500/rate));Check(p.Trained(3300)==2&&p.Queue.Count==0,"offline elapsed time traverses multiple levels");double points=p.Points[3300];p.Advance(p.ProcessedUtc);Check(p.Points[3300]==points,"repeat timestamp cannot award SP twice");p.Advance(t);Check(p.Points[3300]==points,"backward clock cannot subtract progress");
 p=new(){ProcessedUtc=t,Injected=[3300],Queue=[new(3300,1)],Paused=true};p.Advance(t.AddHours(1));Check(p.Points.Count==0,"paused interval earns zero SP");p.Paused=false;p.Advance(t.AddHours(1).AddMinutes(1));Check(Math.Abs(p.Points[3300]-p.Rate(3300,t))<.001,"resume does not bank paused time");
 p=new(){ProcessedUtc=t,Queue=[new(3300,1)]};p.Advance(t.AddDays(1));Check(p.Points.Count==0&&p.Queue.Count==1,"missing skillbook blocks queue");p.Injected.Add(3300);p.Advance(t.AddDays(1).AddMinutes(1));Check(p.Points[3300]<100,"book injection does not recover blocked time");
 p=new(){ProcessedUtc=t,Injected=[3300],Queue=[new(3300,5)],AcceleratorBonus=10,AcceleratorExpiresUtc=t.AddMinutes(5)};double expected=p.Rate(3300,t)*5+p.Rate(3300,t.AddMinutes(5))*5;p.Advance(t.AddMinutes(10));Check(Math.Abs(p.Points[3300]-expected)<.001,"accelerator expiration splits elapsed training exactly");
 p=new();var prereq=SkillCatalog.All.First(s=>s.Requirements.Length>0);var chain2=p.Expand([new(prereq.Id,1)],false);p.Queue=chain2;Check(!p.Move(chain2.Count-1,0),"reorder rejects training before prerequisites");p.Remove(0);Check(p.Validate(p.Queue).Length==0,"removing prerequisite prunes dependent queue entries");
 p=new();foreach(var s in SkillCatalog.All)p.Injected.Add(s.Id);int limit=0;foreach(var s in SkillCatalog.All){var add=p.Expand([new(s.Id,5)]);if(p.Queue.Count+add.Count>150)continue;p.Queue.AddRange(add);if(p.Queue.Count>140)break;}limit=p.Queue.Count;var target=SkillCatalog.All.First(s=>p.Expand([new(s.Id,5)]).Count>150-limit);Check(p.Add([new(target.Id,5)]).Length>0&&p.Queue.Count==limit,"queue capacity failure is atomic");
 p=new(){Injected=[3300],Unallocated=300};Check(p.Apply(3300,1).Length==0&&p.Trained(3300)==1&&p.Unallocated==50,"unallocated SP capped at target level");p=new();Check(p.Remap(new(){[164]=19,[165]=27,[166]=19,[167]=17,[168]=17},DateTime.UtcNow).Length==0,"valid 99 point neural remap");Check(p.Remap(new(){[164]=19,[165]=27,[166]=19,[167]=17,[168]=17},DateTime.UtcNow).Length==0&&p.BonusRemaps==1,"bonus remap consumed while annual unavailable");Check(p.Remap(new(){[164]=20,[165]=27,[166]=19,[167]=17,[168]=17},DateTime.UtcNow).Length>0,"invalid point budget rejected");
 var world=new DemoWorld();world.NewGame(0);world.Credits=1000000;var hull=FleetCatalog.Source("Paladin");Check(world.SkillError(hull.Id).Length>0&&!world.BoardFleetHull(hull.Id),"advanced hull boarding is gated");var goals=SkillCatalog.Required(hull.Id);world.Skills.Grant(goals);world.SyncSkills();Check(world.SkillError(hull.Id).Length==0,"trained direct hull requirements qualify");
 var weapon=WeaponCatalog.All.First(w=>SkillCatalog.Required(w.Id).Any(r=>world.Skills.Trained(r.Skill)<r.Level));Check(world.FitError(weapon,0).StartsWith("Requires"),"native weapon fitting reports required skill names");world.Hangar[weapon.Id]=1;decimal stock=world.Hangar[weapon.Id];Check(!world.FitWeapon(weapon.Id,true,0)&&world.Hangar[weapon.Id]==stock,"failed skill fitting consumes no inventory");var sim=new FittingSimulation(world.Player);Check(sim.World.SkillError(weapon.Id).Length==0,"detached fitting simulation bypasses qualification checks");
 var ship=new Ship();double raw=ship.Stat("cpuOutput");ship.SkillLevels[SkillCatalog.Id("CPU Management")]=5;Check(Math.Abs(ship.Stat("cpuOutput")/raw-1.25)<.00001,"CPU management affects live ship stats");var gun=WeaponCatalog.All.First(w=>w.UsesTurret);ship.SkillLevels[3300]=5;Check(ship.SkillWeapon(gun,"cycle")<1,"gunnery affects weapon projection");
 world=new();world.NewGame(0);world.Credits=100000;world.Skills=new();world.Skills.Grant([new(3300,2)]);world.Skills.Injected.Add(3300);world.Skills.Queue=[new(3300,3)];world.Skills.ProcessedUtc=DateTime.UtcNow.AddHours(-1);world.SyncSkills();Check(world.Skills.Points[3300]>g.Threshold(2),"world services training progress");
 string? old=Environment.GetEnvironmentVariable("STARLIGHT_SAVE_DIR");string directory=Path.Combine(Path.GetTempPath(),"ss-skills36-"+Guid.NewGuid().ToString("N"));Environment.SetEnvironmentVariable("STARLIGHT_SAVE_DIR",directory);try{world.Save();var loaded=new DemoWorld();Check(loaded.Load()&&loaded.Skills.Trained(3300)==2&&loaded.Skills.Queue.Count==1,"save/load retains SP and queue");var json=System.Text.Json.Nodes.JsonNode.Parse(File.ReadAllText(DemoWorld.SavePath))!;json.AsObject().Remove("PilotSkills");File.WriteAllText(DemoWorld.SavePath,json.ToJsonString());loaded=new();Check(loaded.Load()&&loaded.Skills.Injected.Count>0,"legacy save migrates existing equipment qualifications");}finally{Environment.SetEnvironmentVariable("STARLIGHT_SAVE_DIR",old);if(Directory.Exists(directory))Directory.Delete(directory,true);}
 Check(SkillCatalog.Database.GameTypes.Where(x=>x.Key.StartsWith("fleet_")).Count()==FleetCatalog.All.Length,"every registry hull has a source requirement mapping");foreach(var d in FittingLayoutModel.ById.Values.Where(d=>d.Kind!="legacy"))Check(SkillCatalog.TypeId(d.Id)>0,"mapped native fitting item "+d.Id);
 Console.WriteLine($"{checks} skill-system checks passed.");}
